// LiquidGlassMaterial: GPU plate material (P0.3). Two cached blur passes over the Dock's ROI of the
// backdrop plus one full-window glass pass, all driven by GlassParameters through constant buffers.
// Slider changes only rewrite constant buffers; textures are re-created only when the ROI size or
// blur downsample factor changes (deferred to the next frame that renders).
#include <d3d11.h>
#include <wrl/client.h>

#include <algorithm>
#include <cmath>
#include <cstring>

#include "log.h"
#include "material.h"

// fxc-generated bytecode (see CMakeLists.txt).
#include "blur_down_ps.h"
#include "blur_ps.h"
#include "glass_ps.h"
#include "glass_vs.h"

using Microsoft::WRL::ComPtr;

namespace dock {
namespace {

struct alignas(16) GlassConstants {
    float plate[4];
    float geom[4];
    float placement[4];
    float sharpMap[4];
    float blurMap[4];
    float optics[4];
    float mixing[4];
    float tone[4];
    float strokeLight[4];
    float fixedLight[4];
    float dynLight[4];
    float tint[4];
    float pointer[4];
    float interact[4];
    float extra[4];
};
static_assert(sizeof(GlassConstants) % 16 == 0, "cbuffer size");

struct alignas(16) BlurConstants {
    float roi[4];
    float backdrop[4];
    float pass[4];
};

// Continuous corner shape, fitted to the macOS Dock corner measured for V0.2 (extent ~1.18 r,
// superellipse exponent ~2.3). Not exposed in Glass Lab, so fixed here.
constexpr float kCornerExtent = 1.18f;
constexpr float kCornerExponent = 2.3f;

class LiquidGlassMaterial final : public IPlateMaterial {
public:
    HRESULT CreateDeviceResources(ID2D1DeviceContext*) override { return S_OK; }
    void ReleaseDeviceResources() override {}
    void DrawShadow(ID2D1DeviceContext*, const PlatePaint&) override {}
    void DrawBody(ID2D1DeviceContext*, const PlatePaint&) override {}
    void DrawRim(ID2D1DeviceContext*, const PlatePaint&) override {}
    const wchar_t* Name() const override { return L"Liquid Glass (GPU, independent HLSL port)"; }
    bool UsesGpu() const override { return true; }

    HRESULT CreateGpuResources(ID3D11Device* device) override {
        device_ = device;
        HRESULT hr;
        if (FAILED(hr = device->CreateVertexShader(g_GlassVS, sizeof(g_GlassVS), nullptr, &vs_))) return hr;
        if (FAILED(hr = device->CreatePixelShader(g_GlassPS, sizeof(g_GlassPS), nullptr, &glassPs_))) return hr;
        if (FAILED(hr = device->CreatePixelShader(g_BlurDownPS, sizeof(g_BlurDownPS), nullptr, &downPs_))) return hr;
        if (FAILED(hr = device->CreatePixelShader(g_BlurPS, sizeof(g_BlurPS), nullptr, &blurPs_))) return hr;
        D3D11_BUFFER_DESC cb{};
        cb.Usage = D3D11_USAGE_DYNAMIC;
        cb.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
        cb.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        cb.ByteWidth = sizeof(GlassConstants);
        if (FAILED(hr = device->CreateBuffer(&cb, nullptr, &glassCb_))) return hr;
        cb.ByteWidth = sizeof(BlurConstants);
        if (FAILED(hr = device->CreateBuffer(&cb, nullptr, &blurCb_))) return hr;
        D3D11_SAMPLER_DESC sd{};
        sd.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
        sd.AddressU = sd.AddressV = sd.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
        sd.MaxLOD = D3D11_FLOAT32_MAX;
        if (FAILED(hr = device->CreateSamplerState(&sd, &sampler_))) return hr;
        D3D11_BLEND_DESC bd{};
        bd.RenderTarget[0].BlendEnable = TRUE;
        bd.RenderTarget[0].SrcBlend = D3D11_BLEND_ONE;
        bd.RenderTarget[0].DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
        bd.RenderTarget[0].BlendOp = D3D11_BLEND_OP_ADD;
        bd.RenderTarget[0].SrcBlendAlpha = D3D11_BLEND_ONE;
        bd.RenderTarget[0].DestBlendAlpha = D3D11_BLEND_INV_SRC_ALPHA;
        bd.RenderTarget[0].BlendOpAlpha = D3D11_BLEND_OP_ADD;
        bd.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
        if (FAILED(hr = device->CreateBlendState(&bd, &premulBlend_))) return hr;
        D3D11_RASTERIZER_DESC rd{};
        rd.FillMode = D3D11_FILL_SOLID;
        rd.CullMode = D3D11_CULL_NONE;
        rd.DepthClipEnable = TRUE;
        if (FAILED(hr = device->CreateRasterizerState(&rd, &raster_))) return hr;
        rd.ScissorEnable = TRUE;  // glass pass: only the plate's own pixels (see RenderGpu)
        if (FAILED(hr = device->CreateRasterizerState(&rd, &scissorRaster_))) return hr;
        return S_OK;
    }

    void ReleaseGpuResources() override {
        texA_.Reset(); texB_.Reset(); rtvA_.Reset(); rtvB_.Reset(); srvA_.Reset(); srvB_.Reset();
        backdropSrv_.Reset(); backdropTex_.Reset();
        raster_.Reset(); scissorRaster_.Reset(); premulBlend_.Reset(); sampler_.Reset(); blurCb_.Reset(); glassCb_.Reset();
        blurPs_.Reset(); downPs_.Reset(); glassPs_.Reset(); vs_.Reset(); device_.Reset();
        blurKeyValid_ = false;
    }

    bool RenderGpu(const GpuPaint& g) override {
        if (!device_ || !g.backdrop || !g.backdrop->texture || !g.params || !g.context || !g.target) return false;
        ID3D11DeviceContext* ctx = g.context;
        const GlassParameters& p = *g.params;
        const BackdropFrame& b = *g.backdrop;
        const float s = g.dpiScale;

        // Backdrop SRV (recreated only when the texture object changes).
        if (b.texture != backdropTex_.Get()) {
            backdropSrv_.Reset();
            backdropTex_ = b.texture;  // holds a reference so the address cannot be reused while cached
            if (FAILED(device_->CreateShaderResourceView(b.texture, nullptr, &backdropSrv_))) {
                backdropTex_.Reset();
                return false;
            }
            blurKeyValid_ = false;
        }

        // Region of interest: the Dock window plus room for blur kernels and refraction offsets.
        const LONG margin = static_cast<LONG>(std::ceil(96.0f * s));
        RECT roi{g.windowScreenRect.left - margin, g.windowScreenRect.top - margin,
                 g.windowScreenRect.right + margin, g.windowScreenRect.bottom + margin};
        RECT clipped{};
        if (!IntersectRect(&clipped, &roi, &b.screenRect)) return false;
        roi = clipped;
        const int q = p.blurDownsample >= 4 ? 4 : 2;
        const UINT tw = static_cast<UINT>((roi.right - roi.left + q - 1) / q);
        const UINT th = static_cast<UINT>((roi.bottom - roi.top + q - 1) / q);
        if (tw == 0 || th == 0) return false;
        if (tw != texW_ || th != texH_ || !texA_) {
            if (FAILED(CreateRoiTextures(tw, th))) return false;
            blurKeyValid_ = false;
        }

        const float radiusPx = p.blurSpread * 40.0f * s;     // Lab: blurSpread x blurMax(40)
        const float sigma = std::max(radiusPx / 2.5f, 0.01f) / q;
        const int taps = std::min(64, static_cast<int>(std::ceil(sigma * 3.0f)));
        const bool same = blurKeyValid_ && blurKey_.frame == b.frameId && EqualRect(&blurKey_.roi, &roi) &&
                          blurKey_.q == q && std::fabs(blurKey_.sigma - sigma) < 1e-4f;
        ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
        ctx->IASetInputLayout(nullptr);
        ctx->VSSetShader(vs_.Get(), nullptr, 0);
        ctx->RSSetState(raster_.Get());
        ctx->PSSetSamplers(0, 1, sampler_.GetAddressOf());
        ctx->OMSetDepthStencilState(nullptr, 0);
        if (!same) {
            RunBlur(ctx, roi, b, q, sigma, taps, tw, th);
            blurKey_ = {b.frameId, roi, q, sigma};
            blurKeyValid_ = true;
            ++blurUpdates_;
        }

        // Glass pass into the back buffer.
        GlassConstants c{};
        const float cx = (g.plateDip.left + g.plateDip.right) * 0.5f * s;
        const float cy = (g.plateDip.top + g.plateDip.bottom) * 0.5f * s;
        Set(c.plate, cx, cy, (g.plateDip.right - g.plateDip.left) * 0.5f * s, (g.plateDip.bottom - g.plateDip.top) * 0.5f * s);
        Set(c.geom, p.radius * s, p.bevelWidth, kCornerExtent, kCornerExponent);
        Set(c.placement, static_cast<float>(g.windowScreenRect.left), static_cast<float>(g.windowScreenRect.top), s, p.opacity);
        Set(c.sharpMap, static_cast<float>(b.screenRect.left), static_cast<float>(b.screenRect.top),
            1.0f / std::max(1L, b.screenRect.right - b.screenRect.left), 1.0f / std::max(1L, b.screenRect.bottom - b.screenRect.top));
        Set(c.blurMap, static_cast<float>(roi.left), static_cast<float>(roi.top), 1.0f / (tw * q), 1.0f / (th * q));
        Set(c.optics, p.refraction, p.refractiveIndex, p.dispersion, p.magnification);
        Set(c.mixing, p.frost, p.saturation, p.brightness, p.density);
        Set(c.tone, p.glassLift, p.dark ? 1.0f : 0.0f, p.reducedTransparency ? 1.0f : 0.0f, p.shadowAmount);
        Set(c.strokeLight, p.strokeWidth, p.strokeOpacity, p.staticReflection ? 1.0f : 0.0f, p.glare);
        Set(c.fixedLight, p.staticTopLight, p.staticBottomLight, p.staticBottomGlow, p.edgeAmount);
        const float a = p.lightAngle * 3.14159265f / 180.0f;
        Set(c.dynLight, p.fresnelAmount, p.specularAmount, std::cos(a), std::sin(a));
        Set(c.tint, p.tintR, p.tintG, p.tintB, p.tintStrength);
        Set(c.pointer, g.pointerX, g.pointerY, g.hover, g.press);
        Set(c.interact, p.interactionStrength, p.interactionRadius, static_cast<float>(p.debugView), g.rotationDeg * 0.0174532925f);
        Set(c.extra, p.bodyTone, p.edgeSoftness * s, p.highlightDim, 0.0f);
        Upload(ctx, glassCb_.Get(), &c, sizeof(c));

        D3D11_VIEWPORT vp{0, 0, static_cast<float>(g.targetWidth), static_cast<float>(g.targetHeight), 0, 1};
        ctx->RSSetViewports(1, &vp);
        // The shader covers the whole target with one triangle and returns nothing outside the plate, but every pixel
        // still ran it: a small plate in a large window (Launchpad's search pill, each Control Center module) paid a
        // window-size pass. The scissor keeps it to the plate, its lens edge, its shadow (11 DIP below) and a defocused
        // outline. A rotated plate (fan capsule) keeps the whole target.
        if (scissorRaster_ && g.rotationDeg == 0.0f) {
            const float m = (16.0f + 2.0f * std::max(p.edgeSoftness, 0.0f)) * s + 2.0f;
            const LONG l = static_cast<LONG>(std::floor(g.plateDip.left * s - m)), t = static_cast<LONG>(std::floor(g.plateDip.top * s - m));
            const LONG r = static_cast<LONG>(std::ceil(g.plateDip.right * s + m)), b = static_cast<LONG>(std::ceil(g.plateDip.bottom * s + m));
            const D3D11_RECT sc{std::max(0L, l), std::max(0L, t), std::min(static_cast<LONG>(g.targetWidth), r), std::min(static_cast<LONG>(g.targetHeight), b)};
            ctx->RSSetState(scissorRaster_.Get());
            ctx->RSSetScissorRects(1, &sc);
        } else ctx->RSSetState(raster_.Get());
        ctx->OMSetRenderTargets(1, &g.target, nullptr);
        const float blendFactor[4] = {0, 0, 0, 0};
        ctx->OMSetBlendState(premulBlend_.Get(), blendFactor, 0xFFFFFFFF);
        ctx->PSSetShader(glassPs_.Get(), nullptr, 0);
        ctx->PSSetConstantBuffers(0, 1, glassCb_.GetAddressOf());
        ID3D11ShaderResourceView* srvs[2] = {backdropSrv_.Get(), srvA_.Get()};
        ctx->PSSetShaderResources(0, 2, srvs);
        ctx->Draw(3, 0);
        ID3D11ShaderResourceView* nullSrvs[2] = {nullptr, nullptr};
        ctx->PSSetShaderResources(0, 2, nullSrvs);
        ctx->OMSetRenderTargets(0, nullptr, nullptr);
        ctx->OMSetBlendState(nullptr, blendFactor, 0xFFFFFFFF);
        ctx->RSSetState(raster_.Get());
        return true;
    }

private:
    static void Set(float* dst, float a, float b, float c, float d) {
        dst[0] = a; dst[1] = b; dst[2] = c; dst[3] = d;
    }

    static void Upload(ID3D11DeviceContext* ctx, ID3D11Buffer* buffer, const void* data, size_t size) {
        D3D11_MAPPED_SUBRESOURCE m{};
        if (SUCCEEDED(ctx->Map(buffer, 0, D3D11_MAP_WRITE_DISCARD, 0, &m))) {
            memcpy(m.pData, data, size);
            ctx->Unmap(buffer, 0);
        }
    }

    HRESULT CreateRoiTextures(UINT w, UINT h) {
        texA_.Reset(); texB_.Reset(); rtvA_.Reset(); rtvB_.Reset(); srvA_.Reset(); srvB_.Reset();
        D3D11_TEXTURE2D_DESC td{};
        td.Width = w;
        td.Height = h;
        td.MipLevels = 1;
        td.ArraySize = 1;
        td.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;  // high precision avoids banding in soft gradients
        td.SampleDesc.Count = 1;
        td.Usage = D3D11_USAGE_DEFAULT;
        td.BindFlags = D3D11_BIND_RENDER_TARGET | D3D11_BIND_SHADER_RESOURCE;
        HRESULT hr;
        if (FAILED(hr = device_->CreateTexture2D(&td, nullptr, &texA_))) return hr;
        if (FAILED(hr = device_->CreateTexture2D(&td, nullptr, &texB_))) return hr;
        if (FAILED(hr = device_->CreateRenderTargetView(texA_.Get(), nullptr, &rtvA_))) return hr;
        if (FAILED(hr = device_->CreateRenderTargetView(texB_.Get(), nullptr, &rtvB_))) return hr;
        if (FAILED(hr = device_->CreateShaderResourceView(texA_.Get(), nullptr, &srvA_))) return hr;
        if (FAILED(hr = device_->CreateShaderResourceView(texB_.Get(), nullptr, &srvB_))) return hr;
        texW_ = w;
        texH_ = h;
        DLOG(L"glass: blur ROI textures %ux%u (downsample)", w, h);
        return S_OK;
    }

    void RunBlur(ID3D11DeviceContext* ctx, const RECT& roi, const BackdropFrame& b, int q, float sigma, int taps,
                 UINT tw, UINT th) {
        D3D11_VIEWPORT vp{0, 0, static_cast<float>(tw), static_cast<float>(th), 0, 1};
        ctx->RSSetViewports(1, &vp);
        ctx->OMSetBlendState(nullptr, nullptr, 0xFFFFFFFF);
        ctx->PSSetConstantBuffers(0, 1, blurCb_.GetAddressOf());
        ID3D11ShaderResourceView* nullSrv[1] = {nullptr};

        BlurConstants c{};
        Set(c.roi, static_cast<float>(roi.left), static_cast<float>(roi.top), static_cast<float>(q), 0);
        Set(c.backdrop, static_cast<float>(b.screenRect.left), static_cast<float>(b.screenRect.top),
            1.0f / std::max(1L, b.screenRect.right - b.screenRect.left), 1.0f / std::max(1L, b.screenRect.bottom - b.screenRect.top));
        Upload(ctx, blurCb_.Get(), &c, sizeof(c));
        ctx->OMSetRenderTargets(1, rtvA_.GetAddressOf(), nullptr);
        ctx->PSSetShader(downPs_.Get(), nullptr, 0);
        ctx->PSSetShaderResources(0, 1, backdropSrv_.GetAddressOf());
        ctx->Draw(3, 0);
        ctx->PSSetShaderResources(0, 1, nullSrv);
        if (taps < 1) return;

        ctx->PSSetShader(blurPs_.Get(), nullptr, 0);
        Set(c.pass, 1.0f / tw, 0.0f, sigma, static_cast<float>(taps));
        Upload(ctx, blurCb_.Get(), &c, sizeof(c));
        ctx->OMSetRenderTargets(1, rtvB_.GetAddressOf(), nullptr);
        ctx->PSSetShaderResources(0, 1, srvA_.GetAddressOf());
        ctx->Draw(3, 0);
        ctx->PSSetShaderResources(0, 1, nullSrv);

        Set(c.pass, 0.0f, 1.0f / th, sigma, static_cast<float>(taps));
        Upload(ctx, blurCb_.Get(), &c, sizeof(c));
        ctx->OMSetRenderTargets(1, rtvA_.GetAddressOf(), nullptr);
        ctx->PSSetShaderResources(0, 1, srvB_.GetAddressOf());
        ctx->Draw(3, 0);
        ctx->PSSetShaderResources(0, 1, nullSrv);
        ctx->OMSetRenderTargets(0, nullptr, nullptr);
    }

    struct BlurKey {
        unsigned long long frame = 0;
        RECT roi{};
        int q = 0;
        float sigma = 0;
    };

    ComPtr<ID3D11Device> device_;
    ComPtr<ID3D11VertexShader> vs_;
    ComPtr<ID3D11PixelShader> glassPs_, downPs_, blurPs_;
    ComPtr<ID3D11Buffer> glassCb_, blurCb_;
    ComPtr<ID3D11SamplerState> sampler_;
    ComPtr<ID3D11BlendState> premulBlend_;
    ComPtr<ID3D11RasterizerState> raster_, scissorRaster_;
    ComPtr<ID3D11Texture2D> texA_, texB_;
    ComPtr<ID3D11RenderTargetView> rtvA_, rtvB_;
    ComPtr<ID3D11ShaderResourceView> srvA_, srvB_, backdropSrv_;
    ComPtr<ID3D11Texture2D> backdropTex_;
    UINT texW_ = 0, texH_ = 0;
    BlurKey blurKey_;
    bool blurKeyValid_ = false;
    unsigned long long blurUpdates_ = 0;
};

}  // namespace

std::unique_ptr<IPlateMaterial> CreateLiquidGlassMaterial() { return std::make_unique<LiquidGlassMaterial>(); }

}  // namespace dock
